 for(const auto& item:out.items){layers.insert(item.cel.layerId);if(item.cel.surface)charge(item.cel.surface->pixels.size());if(item.mask){masks.insert(item.mask->mask.id);charge(item.mask->mask.surface.pixels.size());}if(item.cel.tilemap)for(const auto& cell:item.cel.tilemap->cells)if(cell)sets.insert(cell->tilesetId);}
